   host.Log=Log;runtime.Log=Log;runtime.Status=s=>Window.Dispatcher.BeginInvoke(new Action(()=>{status.Text=s;if(loadText!=null&&loadText.Visibility==Visibility.Visible)loadText.Text=s;}));
