  static T Ancestor<T>(DependencyObject d)where T:DependencyObject{while(d!=null){if(d is T)return(T)d;d=VisualTreeHelper.GetParent(d);}return null;}
  void Log(string value){if(string.IsNullOrWhiteSpace(value))return;lock(journal){journal.AppendLine(DateTime.Now.ToString("HH:mm:ss")+" "+value.Trim());if(journal.Length>120000)journal.Remove(0,40000);}try{lock(journal)File.AppendAllText(System.IO.Path.Combine(runtime.Root,"auremu.log"),value+Environment.NewLine,Encoding.UTF8);}catch{}}
  async Task Work(Func<Task> action,string done)
  {
   if(busy){status.Text="Дождитесь завершения операции…";return;}busy=true;status.Text="Выполняется операция…";
   try{await action();status.Text=done;}catch(Exception ex){Log(ex.ToString());status.Text="Операция не завершена · откройте журнал";if(!closing)MessageBox.Show(Window,ex.Message,"Auremu",MessageBoxButton.OK,MessageBoxImage.Information);}finally{busy=false;}
  }
