  void FitDisplay(){if(display==null||host==null)return;double ratio=runtime.AspectRatio,w=Math.Max(1,display.ActualWidth),h=Math.Max(1,display.ActualHeight);if(w/h>ratio)w=h*ratio;else h=w/ratio;host.Width=w;host.Height=h;}
  void KeepOnScreen(){if(Window.WindowState!=WindowState.Normal)return;var area=SystemParameters.WorkArea;Window.Left=Math.Max(area.Left,Math.Min(Window.Left,area.Right-Window.Width));Window.Top=Math.Max(area.Top,Math.Min(Window.Top,area.Bottom-Window.Height));}
  void FrameSpacing(bool playing){var frame=(Grid)Window.Content;bool approved=playing&&runtime.Stock;frame.Margin=new Thickness(approved?0:playing?8:12);top.Visibility=approved?Visibility.Collapsed:Visibility.Visible;frame.RowDefinitions[0].Height=new GridLength(approved?0:playing?48:64);frame.RowDefinitions[2].Height=new GridLength(playing?0:28);status.Visibility=playing?Visibility.Collapsed:Visibility.Visible;}
  void ShowManager(){isPlayer=false;FrameSpacing(false);player.Visibility=Visibility.Collapsed;manager.Visibility=Visibility.Visible;Window.MinWidth=1100;Window.MinHeight=760;if(Window.WindowState==WindowState.Normal){Window.Width=Math.Min(1320,SystemParameters.WorkArea.Width-30);Window.Height=Math.Min(900,SystemParameters.WorkArea.Height-30);}KeepOnScreen();BuildHeader();BuildManager();}
  void ShowPlayer(){isPlayer=true;FrameSpacing(true);manager.Visibility=Visibility.Collapsed;player.Visibility=Visibility.Visible;if(runtime.Stock){var layout=PlayerDesign;Window.MinWidth=runtime.Engine.Settings.Form=="mobile"?380:960;Window.MinHeight=640;if(Window.WindowState==WindowState.Normal){Window.Width=Math.Min(layout.w,SystemParameters.WorkArea.Width-24);Window.Height=Math.Min(layout.h,SystemParameters.WorkArea.Height-24);}KeepOnScreen();BuildHeader();Window.UpdateLayout();LayoutApprovedPlayer();RoundWindow();return;}bool mobile=runtime.Engine.Settings.Form=="mobile";Window.MinWidth=mobile?380:960;Window.MinHeight=mobile?640:650;if(Window.WindowState==WindowState.Normal){double height=Math.Min(745,SystemParameters.WorkArea.Height-24);Window.Width=mobile?Math.Max(380,(height-(runtime.Stock?72:112))*runtime.AspectRatio+64):Math.Min(1320,SystemParameters.WorkArea.Width-30);Window.Height=mobile?height:Math.Min(870,SystemParameters.WorkArea.Height-30);}KeepOnScreen();BuildHeader();Window.UpdateLayout();FitDisplay();RoundWindow();}
  async Task Launch(){if(AndroidSetup.Needed(runtime)){if(!await FirstRunDialog())return;}await Work(async()=>{ShowPlayer();loadText.Visibility=Visibility.Visible;Exception failure=null;try{await runtime.Start();if(runtime.Stock)ShowPlayer();host.Visibility=Visibility.Visible;Window.UpdateLayout();FitDisplay();runtime.StartMirror();await runtime.WaitMirrorReady();if(!host.Attached)await host.Attach(runtime.MirrorTitle,runtime.Mirror.Id);if(!host.Attached||runtime.Mirror.HasExited)throw new Exception("Модуль отображения Android не подключён.");loadText.Visibility=Visibility.Collapsed;}catch(Exception ex){failure=ex;}if(closing)return;if(failure!=null){host.Visibility=Visibility.Collapsed;host.Detach();if(runtime.Ready)await runtime.Stop();ShowManager();throw failure;}},"Android готов · экран подключён");}
