  async Task InstallApk(){if(!runtime.Ready)return;var f=new OpenFileDialog{Filter="Android APK|*.apk",Title="Установить APK в Auremu"};if(f.ShowDialog(Window)!=true)return;await Work(async()=>{await runtime.Adb("install","-r",f.FileName);await runtime.SetTheme(runtime.Engine.Settings.PlayerTheme);},"Приложение установлено");}
