  async Task Record(){if(!runtime.Ready)return;await Work(async()=>{if(recording!=null&&!recording.HasExited){await runtime.Adb("shell","pkill","-INT","screenrecord");await Task.Run(()=>recording.WaitForExit(6000));await runtime.Adb("pull","/sdcard/auremu-recording.mp4",recordingFile);recording=null;status.Text="Запись сохранена: "+recordingFile;return;}var dir=System.IO.Path.Combine(runtime.Root,"captures");Directory.CreateDirectory(dir);recordingFile=System.IO.Path.Combine(dir,DateTime.Now.ToString("yyyyMMdd-HHmmss")+".mp4");recording=Process.Start(Aemu.Runner.Info(runtime.Engine.Adb,new[]{"-s",runtime.Serial,"shell","screenrecord","/sdcard/auremu-recording.mp4"},runtime.Engine.Settings.Sdk,runtime.Engine.AvdRoot));recording.StandardInput.Close();recording.BeginOutputReadLine();recording.BeginErrorReadLine();},recording==null?"Запись сохранена":"Запись идёт · нажмите ещё раз для остановки");}
