  void DeviceOptions(){var cpu=new ComboBox{ItemsSource=new[]{2,4,6,8},SelectedItem=runtime.Engine.Settings.Cores};var ram=new ComboBox{ItemsSource=new[]{2048,4096,6144,8192},SelectedItem=runtime.Engine.Settings.Memory};var gpu=new ComboBox{ItemsSource=new[]{"auto","host","software"},SelectedItem=runtime.Engine.Settings.Gpu};Window dialog=null;var save=Btn("Сохранить",()=>{runtime.Engine.Settings.Cores=(int)cpu.SelectedItem;runtime.Engine.Settings.Memory=(int)ram.SelectedItem;runtime.Engine.Settings.Gpu=(string)gpu.SelectedItem;runtime.Engine.Save();dialog.Close();status.Text="Настройки применятся при следующем запуске";},true);dialog=Dialog("Устройство",Stack(Text("Параметры устройства",23),Text("Ядра CPU"),cpu,Text("Память, МБ"),ram,Text("Графика"),gpu,save));dialog.ShowDialog();}
  void VolumeDialog(){var slider=new Slider{Minimum=0,Maximum=100,Value=runtime.Engine.Settings.Volume};Window d=null;d=Dialog("Громкость",Stack(Text("Громкость Android",22),slider,Btn("Применить",async()=>{runtime.Engine.Settings.Volume=(int)slider.Value;runtime.Engine.Save();d.Close();await Work(async()=>await runtime.Adb("shell","cmd","media_session","volume","--stream","3","--set",((int)(slider.Value*15/100)).ToString()),"Громкость изменена");},true)));d.ShowDialog();}
  void Gps(){if(!runtime.Ready)return;var lat=new TextBox{Text="41.2995"};var lon=new TextBox{Text="69.2401"};Window d=null;d=Dialog("Геолокация",Stack(Text("Геолокация Android",23),Text("Широта"),lat,Text("Долгота"),lon,Btn("Передать координаты",async()=>{double a,b;if(!double.TryParse(lat.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out a)||!double.TryParse(lon.Text,NumberStyles.Float,CultureInfo.InvariantCulture,out b)||Math.Abs(a)>90||Math.Abs(b)>180){MessageBox.Show(d,"Проверьте координаты.");return;}d.Close();await Work(async()=>await runtime.Adb("emu","geo","fix",b.ToString(CultureInfo.InvariantCulture),a.ToString(CultureInfo.InvariantCulture)),"Геопозиция передана");},true)));d.ShowDialog();}
